#define _GNU_SOURCE
#include <pthread.h>
#include <sched.h>
#include <cstdio>

// Pin the calling thread to a single physical core.
bool pin_to_core(int core) {
    cpu_set_t set;
    CPU_ZERO(&set);
    CPU_SET(core, &set);
    int rc = pthread_setaffinity_np(pthread_self(), sizeof(set), &set);
    if (rc != 0) { perror("setaffinity"); return false; }
    // verify
    CPU_ZERO(&set);
    pthread_getaffinity_np(pthread_self(), sizeof(set), &set);
    printf("pinned to core %d? %d (running on %d)\n",
           core, CPU_ISSET(core, &set), sched_getcpu());
    return true;
}

// Strategy thread entry: pin first, then warm/init memory (first-touch local).
void strategy_main(int core) {
    pin_to_core(core);
    // touch/zero buffers HERE so pages land on this core's NUMA node
    // ... busy-spin event loop ...
}

void strategy_thread() {
    pin_to_core(6);                 // 1) bind first
    auto* buf = new (std::align_val_t(64)) Event[1 << 16];
    for (auto& e : std::span(buf, 1 << 16)) e = Event{}; // 2) first-touch -> node 0
    // 3) verify
    assert(sched_getcpu() == 6);
    run_loop(buf);                  // 4) busy-spin
}
